import java.util.*;

public class Cutting {

    public static void main(String[] args) {
        Scanner inputScanner = new Scanner(System.in);
        String firstInput = inputScanner.nextLine();
        String[] tokens = firstInput.split(" ");
        int totalSegments = Integer.parseInt(tokens[0]);
        int availableCoins = Integer.parseInt(tokens[1]);
        String[] segmentValues = inputScanner.nextLine().split(" ");
        int oddSegments = 0;
        int evenSegments = 0;
        int totalCutsMade = 0;
        List<Integer> differenceList = new ArrayList<>();
        for (int i = 0; i < totalSegments - 1; i++) {
            int currentValue = Integer.parseInt(segmentValues[i]);
            if (currentValue % 2 == 0) {
                evenSegments++;
            } else {
                oddSegments++;
            }
            if (oddSegments == evenSegments) {
                int nextValue = Integer.parseInt(segmentValues[i + 1]);
                int diff = Math.abs(nextValue - currentValue);
                differenceList.add(diff);
            }
        }
        Collections.sort(differenceList);
        for (int difference : differenceList) {
            if (difference <= availableCoins) {
                availableCoins -= difference;
                totalCutsMade++;
            } else {
                break;
            }
        }
        System.out.println(totalCutsMade);
    }
}
