#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdlib>

int main() {
    int totalSegments, availableCoins;
    std::cin >> totalSegments >> availableCoins;
    std::vector<int> segmentValues(totalSegments);
    for (int i = 0; i < totalSegments; ++i) {
        std::cin >> segmentValues[i];
    }

    int oddSegments = 0;
    int evenSegments = 0;
    int totalCutsMade = 0;
    std::vector<int> differenceList;

    for (int i = 0; i < totalSegments - 1; ++i) {
        int currentValue = segmentValues[i];
        if (currentValue % 2 == 0) {
            ++evenSegments;
        } else {
            ++oddSegments;
        }
        if (oddSegments == evenSegments) {
            int nextValue = segmentValues[i + 1];
            int diff = std::abs(nextValue - currentValue);
            differenceList.push_back(diff);
        }
    }

    std::sort(differenceList.begin(), differenceList.end());

    for (int difference : differenceList) {
        if (difference <= availableCoins) {
            availableCoins -= difference;
            ++totalCutsMade;
        } else {
            break;
        }
    }

    std::cout << totalCutsMade << std::endl;
    return 0;
}
